import { IProduct } from "@/src/domain/models/IProduct"
import { google } from "googleapis"

const SCOPES = ["https://www.googleapis.com/auth/spreadsheets.readonly"]

const getEnv = (name: string): string => {
    const value = process.env[name]
    if (!value) throw new Error(`Missing environment variable: ${name}`)
    return value
}

// Keys generated by Railway when splitting the service account JSON into
// separate environment variables.
const CREDENTIAL_KEYS = [
    "type",
    "project_id",
    "private_key_id",
    "private_key",
    "client_email",
    "client_id",
    "auth_uri",
    "token_uri",
    "auth_provider_x509_cert_url",
    "client_x509_cert_url",
    "universe_domain",
] as const

const buildCredentials = (): Record<string, string> => {
    const credentials: Record<string, string> = {}
    for (const key of CREDENTIAL_KEYS) {
        // Env vars flatten real newlines into literal "\n";
        // Google Auth requires them back as actual newlines.
        credentials[key] = key === "private_key"
            ? getEnv(key).replace(/\\n/g, "\n")
            : getEnv(key)
    }
    return credentials
}

// Lazily initialized so the module can be imported without credentials
// (e.g. during build) without throwing.
let sheets: ReturnType<typeof google.sheets> | undefined

const getSheets = () => {
    if (!sheets) {
        const auth = new google.auth.GoogleAuth({
            credentials: buildCredentials(),
            scopes: SCOPES,
        })

        sheets = google.sheets({ version: "v4", auth })
    }

    return sheets
}

const SPREADSHEET_ID = "1u1KX0KbZa1-To78M0oErqRZxvrXDxKZq9s2F9CnKk8M"

const getItems = async () => {
    const res = await getSheets().spreadsheets.values.get({
        spreadsheetId: SPREADSHEET_ID,
        range: "Hoja 1!A1:Z100",
    })

    const items = res.data.values?.slice(1) ?? []

    const productsList: IProduct[] = items.map((item: string[], index: number) => {
        let details = []
        try {
            details = item[3] ? JSON.parse(item[3]) : []
        } catch (error) {
            console.error("Error al parsear details en fila", index, error)
        }

        return {
            id: String(index + 1),
            title: item[0],
            price: Number(item[1]),
            description: item[2],
            details,
            image: item[4],
            link: `/product/${index + 1}`,
            isPersonalized: item[5] === "TRUE" ? true : false,
        }
    })

    return productsList
}

export const getProductById = async (id: string): Promise<IProduct | undefined> => {
    const products = await getProducts()
    return products.find((product) => product.id === id) as IProduct
}

export const getProducts = async (): Promise<IProduct[]> => {
    const items = await getItems()

    return items
}
